export const getAllProjects = () => projects;
export const getProjectBySlug = (slug) => projects.find((p) => p.slug === slug);
export const getFeaturedProject = () => projects.find((p) => p.featured);
export const getProjectsByCategory = (categoryId) =>
  !categoryId || categoryId === "all"
    ? projects
    : projects.filter((p) => p.primaryCategory === categoryId || p.secondaryCategories.includes(categoryId));
export const getProjectsLinkingToInsightSlug = (slug) =>
  projects.filter((p) => p.relatedInsightSlugs.includes(slug));
